import {CARRIAGES,DESTINATIONS,REGIONS,STAMP_PROJECTS,TYPE_ORDER,ACHIEVEMENTS,PAINTS,DECOR,SIGHTINGS,STORAGE_KEY,MAX_ROOM_LEVEL,ROOM_GRADES,SERVICE_MILESTONES,LIVERY_FILTERS,ENGINES,TALES,HERITAGE_PROJECTS,SEASONS,WORKSHOP_STAGES,SERVICE_RANKS,SERVICE_CATALOG,ROOM_CATEGORIES,ECONOMY_RATE_SCALE} from './data.js';
import {initialState,validateState,offlineCredit,collect,buildCar,upgradeCar,hireResident,hireCost,buyDecor,moveCar,tick,capacity,satisfaction,incomeRate,carIncomeRate,carCost,upgradeCost,buyPaint,buyTrainUpgrade,trainUpgradeCost,formatCoins,claimSighting,carriageGate,nextDestination,regionGate,unlockRegion,travelRegion,buyStampProject,nextResident,canStartSeason,startSeason,setAutoTour,roomGrade,nextRoomGrade,ridersCount,journeyDuration,journeyMotion,renameTrain,refitCost,refitGate,queueRefit,engineGate,selectEngine,visualSeason,setVisualSeason,heritageGate,buyHeritage,trainIncomeContext,passengerManifest,workshopRank,workshopGate,workshopCost,buyWorkshop,serviceRank,claimServiceRank,gradeUpgradeQuote,buyNextGrade,buildingTime,renovationTime,roomBusy,underConstruction,isHousing,serviceSlots,stockRemaining,stockCapacity,deliveryRemaining,supplyQuote,orderSupply,orderAllSupplies,orderTrainSupplies,crewHousingCapacity,crewHoused,crewHireGate} from './economy.js';
import {LivingScene} from './art.js';
import {loadGame,saveGame,clearGame,storageForSlot,canOpenFleet,loadBackup} from './save.js';
const el=/** @type {(id:string)=>any} */(id=>document.getElementById(id));const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sleeper:'☾',cafe:'☕',garden:'❀',library:'▣',diner:'♨',arcade:'✦',workshop:'⚒',observatory:'✧',postal:'✉',bakery:'♨',cinema:'▤',lounge:'◈'};
const picture={sleeper:'car-sleeper.png',cafe:'car-cafe.png',garden:'car-garden.png',library:'car-library.svg',diner:'car-diner.svg',arcade:'car-arcade.png',workshop:'car-workshop.svg',observatory:'car-observatory.png',postal:'car-postal.svg',bakery:'car-bakery.svg',cinema:'car-cinema.svg',lounge:'car-lounge.svg',quarters:'car-quarters.svg',newsstand:'car-newsstand.svg',tea:'car-tea.svg',barber:'car-barber.svg',florist:'car-florist.svg',music:'car-music.svg',apothecary:'car-apothecary.svg',photography:'car-photography.svg',tailor:'car-tailor.svg',aquarium:'car-aquarium.svg',cheese:'car-cheese.svg',museum:'car-museum.svg',pottery:'car-pottery.svg',bookshop:'car-bookshop.svg',suite:'car-suite.svg',planetarium:'car-planetarium.svg'};
const roomPicture=type=>path(picture[type]);
const regionPicture=id=>id==='heartland'?path('world.webp'):path('region-'+id+'.svg');
const path=name=>new URL('../assets/'+name,import.meta.url).href;
let state,offline=0,recovered=false,saveSource='new',saveConflict=false;let active=null,mode='train',shopPage='cars',catalogFilter='All',journalPage='postcards',lastTick=Date.now(),lastUi=0,lastSave=0,toastTimer;
let scenic=false,audioEnabled=false,lowPower=false,activeSlot=0,fleetUnlocked=false,gameStorage;
try{fleetUnlocked=localStorage.getItem('everline-fleet-unlocked')==='true';const n=Number(localStorage.getItem('everline-active-slot'));activeSlot=fleetUnlocked&&Number.isInteger(n)&&n>=0&&n<3?n:0;gameStorage=storageForSlot(localStorage,activeSlot);lowPower=localStorage.getItem('everline-low-power')==='true';}catch{}
let motion=!window.matchMedia('(prefers-reduced-motion:reduce)').matches;
try{motion=localStorage.getItem('everline-motion')==='false'?false:motion;const result=loadGame(gameStorage);state=result.state||initialState();recovered=result.recovered;saveSource=result.source||'new';offline=offlineCredit(state);}catch(err){state=initialState();offline=0;setTimeout(()=>toast('Browser storage unavailable. Export your save to keep a backup.'),600);}
const scene=new LivingScene(el('world'),i=>choose(i),()=>takeSighting());scene.state=state;scene.motion=motion;scene.lowPower=lowPower;scene.resize();scene.focus(state.selected);document.addEventListener('visibilitychange',()=>{if(document.hidden)persist(true);else{const now=Date.now();tick(state,Math.min(28800,Math.max(0,(now-lastTick)/1000)),{offline:true});lastTick=now;persist(true);refresh();scene.resize();}});window.addEventListener('pagehide',()=>{if(!document.hidden)persist(true)});
window.addEventListener('storage',e=>{if((e.key===null||[STORAGE_KEY,'everline-save-v5','everline-save-v4'].map(k=>activeSlot===0?k:`everline-fleet-${activeSlot}:${k}`).includes(e.key))){saveConflict=true;toast('This train changed in another tab. Reload to prevent overwriting its progress.')}});
function persist(force=false){if(saveConflict)return;try{if(!fleetUnlocked&&canOpenFleet(state)){localStorage.setItem('everline-fleet-unlocked','true');fleetUnlocked=true;}}catch{}const now=Date.now();if(!force&&now-lastSave<3300)return;lastSave=now;state.lastTime=now;try{saveGame(gameStorage,state)}catch(e){toast('Saving unavailable here; use Export Save from Settings.')}}
function toast(message){const item=el('toast');item.textContent=message;item.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>item.classList.remove('show'),3200)}
function progress(msg=''){if(msg)toast(msg);persist(true);refresh();if(mode==='shop')renderShop();if(mode==='journal')renderJournal();}
function choose(index){if(scenic)return;if(!Number.isInteger(index)||index<-1||index>=state.cars.length)return;state.selected=index;scene.focus(index);if(mode!=='train')closeDrawer();refresh();persist()}
function eta(){return Math.max(0,Math.ceil(journeyDuration(state)-state.stationProgress))}
function timeText(seconds){const n=Math.ceil(Math.max(0,seconds));return n>=3600?`${Math.floor(n/3600)}h ${Math.ceil(n%3600/60)}m`:n>=60?`${Math.ceil(n/60)}m`:`${n}s`;}
function clock(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function refresh(){el('coins').textContent=formatCoins(state.coins);el('pending').textContent='+'+formatCoins(state.pending);el('stamps').textContent=String(state.stamps);const motionState=journeyMotion(state);el('eta').textContent=motionState.phase==='platform'?'AT STOP':clock(eta());const arrivalLabel=document.querySelector('.arrival');if(arrivalLabel)arrivalLabel.textContent=motionState.phase==='platform'?'At station':motionState.phase==='approaching'?'Slowing for':motionState.phase==='departing'?'Departing':'Arrival in';
 const status=el('journey-status');if(status){status.textContent=motionState.phase==='approaching'?'SLOWING FOR STATION':motionState.phase==='platform'?'BOARDING & ALIGHTING':motionState.phase==='departing'?'PULLING AWAY':'ON THE OPEN RAIL';status.dataset.phase=motionState.phase;}el('location').textContent='NEXT STOP: '+nextDestination(state).name.toUpperCase()+' · '+REGIONS.find(r=>r.id===state.activeRegion).name.toUpperCase()+' · '+visualSeason(state).toUpperCase();const unclaimed=SERVICE_RANKS.filter(r=>state.totalStops>=r.stops&&!state.rankClaims.includes(r.id)).length;const journal=document.querySelector('[data-page="journal"]');if(journal instanceof HTMLElement){journal.classList.toggle('has-rank-reward',unclaimed>0);journal.setAttribute('aria-label',unclaimed?`Journal · ${unclaimed} service rank rewards available`:'Journal');}renderInspector();renderTour();el('sighting').hidden=!active;scene.sighting=active;}
// Avoid tearing down the focused button on every half-second HUD update.
const inspectorCache=new WeakMap();
function updateInspectorMarkup(e,html){if(inspectorCache.get(e)===html)return;const focus=document.activeElement;const key=focus instanceof HTMLButtonElement&&e.contains(focus)?[focus.dataset.action,focus.dataset.id,focus.dataset.direction]:null;e.innerHTML=html;inspectorCache.set(e,html);if(key){const replacement=Array.from(e.querySelectorAll('button')).find(b=>b.dataset.action===key[0]&&b.dataset.id===key[1]&&b.dataset.direction===key[2]);if(replacement&&!replacement.disabled)replacement.focus({preventScroll:true});else el('world').focus({preventScroll:true});}}
function renderInspector(){const e=el('inspector-inner');const index=state.selected;
 if(index<0){updateInspectorMarkup(e,`<div class="room-kicker">THE ENGINE · NO. 001</div><div class="room-title"><span class="room-icon">✦</span><div><h2 class="room-name">${safe(state.trainName)}</h2><div class="room-earn">${formatCoins(incomeRate(state)*60)} coins / min</div></div></div><div class="train-summary"><p>${state.cars.length} carriages · ${ridersCount(state)} passengers aboard · ${satisfaction(state)}% happiness</p><p>One small railway, a thousand big stories.</p></div><button class="upgrade" data-action="open-shop">BUILD A CARRIAGE ➜</button>`);return;}
 const car=state.cars[index],cfg=CARRIAGES[car.type];if(!car||!cfg)return;const rate=carIncomeRate(state,index)*3600;const price=upgradeCost(car),reserved=(car.pendingCrew||[]).length,hire=hireCost({...car,staff:car.staff+reserved}),full=car.level>=MAX_ROOM_LEVEL;const hireGate=crewHireGate(state,car.id);const prospect=nextResident(state),matched=prospect.dream===car.type;const crew=(car.crew||[]).map(p=>safe(p.name)+(p.dream===car.type?' ★':'')).join(' · ');
 const forecast=full?0:Math.max(0,carIncomeRate({...state,cars:state.cars.map(c=>c.id===car.id?{...c,level:c.level+1}:c)},index)*3600-rate);
 const bars=Array.from({length:MAX_ROOM_LEVEL},(_,j)=>`<i class="${j<car.level?'lit':''}"></i>`).join('');
 updateInspectorMarkup(e,`<div class="room-kicker">CARRIAGE ${String(index+1).padStart(2,'0')} · ${safe(cfg.label.toUpperCase())}</div><div class="room-title"><span class="room-icon">${icons[car.type]||'✦'}</span><div><h2 class="room-name">${safe(cfg.name)}</h2><div class="room-earn">Earns <span class="inline-coin" aria-label="coins"></span> ${formatCoins(rate)} <span class="per-hour">/ hr</span></div></div></div><div class="level-line"><span>LEVEL ${car.level} <small>/ ${MAX_ROOM_LEVEL}</small></span><strong>${car.staff} / 2 CREW · ${car.riders??0} PASSENGERS</strong></div><div class="level-track" aria-label="Room level ${car.level} of ${MAX_ROOM_LEVEL}">${bars}</div><div class="grade-line"><b>${safe(roomGrade(car.level).name.toUpperCase())} INTERIOR${workshopRank(car)?` · W${workshopRank(car)}`:''}</b><span>${nextRoomGrade(car.level)?'NEW VISUAL STYLE AT LEVEL '+nextRoomGrade(car.level).level:'FINAL CARRIAGE STYLE'}</span></div><div class="crew-roster">${car.pendingRefit?'REFIT AT NEXT STOP · '+safe(CARRIAGES[car.pendingRefit].name)+' · ':''}${crew?'ON BOARD · '+crew:'NEXT APPLICANT · '+safe(prospect.name)+' · '+safe(prospect.craft)+(matched?' · DREAM ROLE BONUS':'')}${reserved?' · '+reserved+' CREW BOARDING AT NEXT STOP':''}</div><button class="upgrade" data-action="upgrade" data-id="${car.id}" ${full||roomBusy(car)||state.coins<price?'disabled':''}>${underConstruction(car)?'BUILDING · '+timeText(car.buildRemaining):car.upgradeRemaining>0?'RESTORING · '+timeText(car.upgradeRemaining):car.pendingRefit?'REFIT SCHEDULED':full?'MASTERWORK COMPLETE':`<span>Upgrade room${renovationTime(car.level)?' · '+timeText(renovationTime(car.level)):''}${forecast?` <small class="upgrade-gain">+${formatCoins(forecast)}/hr</small>`:''}</span> <strong><i class="inline-coin" aria-hidden="true"></i>${formatCoins(price)}</strong>`}</button><div class="service-summary"><span>${isHousing(car)?'RESIDENTIAL · RENT':`${serviceSlots(car)} SERVICES · ${Array.from({length:serviceSlots(car)},(_,i)=>stockRemaining(car,i)>0).filter(Boolean).length} STOCKED`}</span><button data-action="open-supplies" data-id="${car.id}">${isHousing(car)?'SERVICE INFO':'SUPPLIES ➜'}</button></div><div class="secondary-tools"><button data-action="hire" data-id="${car.id}" ${!hireGate.ok?'disabled':''}>${car.staff+reserved>=2?'CREW FULL':crewHoused(state)>=crewHousingCapacity(state)?'NEED BERTHS':`HIRE ${safe(prospect.name.toUpperCase())} · ${formatCoins(hire)}`}</button><button class="move-btn" title="Move carriage left" aria-label="Move room left" data-action="move" data-id="${car.id}" data-direction="-1" ${index===0?'disabled':''}>←</button><button class="move-btn" title="Move carriage right" aria-label="Move room right" data-action="move" data-id="${car.id}" data-direction="1" ${index===state.cars.length-1?'disabled':''}>→</button></div>`);
}
function renderTour(){const t=el('tour');if(state.tutorial>=3){if(t.innerHTML)t.innerHTML='';t.dataset.step='3';return;}
 if(t.dataset.step===String(state.tutorial))return;t.dataset.step=String(state.tutorial);if(state.tutorial===0)t.innerHTML='<strong>WELCOME ABOARD · 1/3</strong><div>Tap the gold + button to collect your coins.</div><button data-action="skip-tutorial">Skip introduction</button>';
 else if(state.tutorial===1)t.innerHTML='<strong>MAKE YOURSELF AT HOME · 2/3</strong><div>Upgrade the selected room using the gold button.</div><button data-action="skip-tutorial">Skip introduction</button>';
 else t.innerHTML='<strong>AND WE’RE OFF! · 3/3</strong><div>Visit the Shop for unique rooms. Supply businesses and return when work is finished.</div><button data-action="finish-tutorial">LET’S GO</button>';
}
function maybeTutorial(step){if(state.tutorial===step){state.tutorial++;persist(true);renderTour();}}
function tabbar(options,current,prefix){return `<div class="subnav">${options.map(([id,name])=>`<button class="${id===current?'current':''}" data-${prefix}="${id}" aria-pressed="${id===current}">${safe(name)}</button>`).join('')}</div>`}
function shopCard(label,desc,pictureSrc,button,labelTop='',extra='',filter='none'){return `<article class="purchase-card ${extra}"><div class="preview">${`<img loading="lazy" style="filter:${filter}" src="${pictureSrc||path('car-engine.png')}" alt="Illustrated preview: ${safe(label)}"/>`}</div><div class="body"><div class="small-kicker">${safe(labelTop)}</div><h3>${safe(label)}</h3><p>${safe(desc)}</p>${button}</div></article>`}
function workshopPreview(car,stage,i){const rendered=scene.roomRaster({...car,level:stage.level,mastery:i+1},1);return rendered?rendered.toDataURL('image/png'):roomPicture(car.type)}
function renderShop(){shopPage=['cars','supplies','refit','engineering','stampworks','decoration','paint','heritage','workshop'].includes(shopPage)?shopPage:'cars';el('drawer-kicker').textContent='LITTLE WORLDS ON RAILS';el('drawer-title').textContent='The Carriage Shop';const tabs=tabbar([['cars','CARRIAGES'],['supplies','SUPPLIES'],['refit','REFIT'],['workshop','ROOM WORKSHOP'],['engineering','ENGINEERING'],['stampworks','STAMP WORKS'],['decoration','DECORATIONS'],['paint','LOCOMOTIVES'],['heritage','HERITAGE']],shopPage,'shop-page');let body='';
 if(shopPage==='cars'){const building=state.cars.find(underConstruction);const owned=new Set(state.cars.map(c=>c.type));body=`<div class="route-note catalog-header"><b>${owned.size}/${TYPE_ORDER.length} blueprints aboard · ${state.cars.length}/25 slots</b><p>${building?'Construction bay: '+safe(CARRIAGES[building.type].name)+' · '+'<span data-build-clock>'+timeText(building.buildRemaining)+'</span> remaining':'One construction bay ready. New carriages are unique; choose your next business.'} Existing duplicate carriages are grandfathered. New additions and refits require a different blueprint.</p><div class="catalog-filters" aria-label="Filter carriage categories">${['All',...ROOM_CATEGORIES].map(c=>`<button data-catalog-filter="${c}" aria-pressed="${catalogFilter===c}">${c}</button>`).join('')}</div></div>`+TYPE_ORDER.filter(type=>catalogFilter==='All'||SERVICE_CATALOG[type].category===catalogFilter).sort((a,b)=>Number(carriageGate(state,b).ok)-Number(carriageGate(state,a).ok)||CARRIAGES[a].unlock-CARRIAGES[b].unlock).map(type=>{const car=CARRIAGES[type],cost=carCost(state,type),gate=carriageGate(state,type),unlock=gate.ok;const price=unlock?`<button data-action="build" data-type="${type}" ${state.coins<cost?'disabled':''}>BUILD · ${formatCoins(cost)} COINS · ${timeText(buildingTime(state))}</button>`:`<button disabled>${safe(gate.reason)}</button>`;return shopCard(car.name,`${car.desc} · ${SERVICE_CATALOG[type].category==='Housing'?'Passive rent':SERVICE_CATALOG[type].products.join(' · ')}`,roomPicture(type),price,`${SERVICE_CATALOG[type].category.toUpperCase()} · ${owned.has(type)?'ABOARD':'BLUEPRINT'}`,unlock?'':'locked')}).join('');}
 if(shopPage==='supplies'){const car=state.cars[state.selected];if(!car)body='<div class="route-note">Select a passenger carriage first.</div>';else{const cfg=SERVICE_CATALOG[car.type];body=`<div class="route-note service-header"><b>${safe(CARRIAGES[car.type].name)} · ${safe(cfg.category)}</b><p>${underConstruction(car)?'Construction · '+timeText(car.buildRemaining)+' remaining.':isHousing(car)?'Housing earns modest rent without supplies and provides crew berths.':'Products earn service revenue while stocked. Boarded crew unlock extra services; dream-role crew increase stock duration. Empty shops earn a small base fare.'} Supplies and projects progress during the credited offline period. Crew berths: ${crewHoused(state)}/${crewHousingCapacity(state)} used.</p><button class="rank-claim" data-action="restock-train" ${state.cars.some(c=>[0,1,2].some(i=>supplyQuote(state,c.id,i).ok))?'':'disabled'}>ORDER ALL TRAIN SUPPLIES</button>${!isHousing(car)?`<button class="rank-claim" data-action="restock-all" data-id="${car.id}" ${[0,1,2].some(i=>supplyQuote(state,car.id,i).ok)?'':'disabled'}>ORDER ALL AVAILABLE SUPPLIES</button>`:''}</div>`+(!isHousing(car)?cfg.products.map((name,i)=>{const q=supplyQuote(state,car.id,i),stock=stockRemaining(car,i),delivery=deliveryRemaining(car,i),locked=i>=serviceSlots(car);const percent=Math.min(100,100*stock/stockCapacity(car,i));return `<article class="supply-ticket"><div class="small-kicker">SERVICE ${i+1} / 3</div><h3>${safe(name)}</h3><p>${locked?'Requires '+i+' boarded crew':delivery>0?'Delivery in <span data-supply-clock="'+i+'">'+timeText(delivery)+'</span>':stock>0?'Stocked · <span data-supply-clock="'+i+'">'+timeText(stock)+'</span> of service remaining':'Out of stock · basic fare only'}</p><div class="supply-meter" data-supply-meter="${i}" role="progressbar" aria-label="${safe(name)} stock" aria-valuenow="${Math.floor(percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div><button data-action="restock" data-id="${car.id}" data-type="${i}" ${q.ok?'':'disabled'}>${q.ok?'ORDER · '+formatCoins(q.cost)+' COINS · '+timeText(q.seconds):safe(q.reason)}</button></article>`}).join(''):'');}}
 if(shopPage==='refit'){const car=state.cars[state.selected];const heading=car?`<div class="route-note">Refit carriage ${state.selected+1} (${safe(CARRIAGES[car.type].name)}). Paid refits complete at the next station. Room level, crew and order are retained. Upgrade purchases are paused until the refit completes. You can choose a different carriage from the train view.</div>`:'<div class="route-note">Select a passenger carriage in the train view before refitting.</div>';body=heading+(car?TYPE_ORDER.filter(t=>t!==car.type).map(type=>{const cfg=CARRIAGES[type],gate=refitGate(state,car.id,type),cost=refitCost(state,car,type);return shopCard(cfg.name,`${cfg.desc} · Keeps room level ${car.level}`,roomPicture(type),`<button data-action="refit" data-id="${car.id}" data-type="${type}" ${gate.ok?'':'disabled'}>${gate.ok?'REFIT · '+formatCoins(cost)+' COINS':safe(gate.reason)}</button>`,'WORKSHOP · NO NEW SLOT',gate.ok?'':'locked')}).join(''):'');}
 if(shopPage==='workshop'){const car=state.cars[state.selected];if(!car)body='<div class="route-note">Select a passenger carriage in Train view to commission its workshop improvements.</div>';else{const rank=workshopRank(car),gate=workshopGate(state,car.id),base=carIncomeRate(state,state.selected),next=WORKSHOP_STAGES[rank],gradeQuote=gradeUpgradeQuote(state,car.id);body=`<div class="route-note workshop-note"><b>${safe(CARRIAGES[car.type].name)} · Carriage ${state.selected+1}</b><p>Room level ${car.level}/20 · Workshop ${rank}/4 · +${rank*12}% base earnings. Commissions are optional, stay with a refit and reset with a new timetable. ${next?`Next commission: +${formatCoins(base*.12/(1+rank*.12)*3600)} coins/hr at current occupancy.`:'All four commissions installed.'}</p>${car.level<MAX_ROOM_LEVEL?`<button class="rank-claim grade-advance" data-action="next-grade" data-id="${car.id}" ${gradeQuote.ok?'':'disabled'}>${gradeQuote.ok?'Restore to level '+gradeQuote.target+' · '+formatCoins(gradeQuote.cost)+' coins':safe(gradeQuote.reason)+' · '+formatCoins(gradeQuote.cost)+' coins to level '+gradeQuote.target}</button>`:''}</div>`+WORKSHOP_STAGES.map((stage,i)=>{const paid=i<rank,available=i===rank&&gate.ok;return shopCard(stage.name,`${stage.detail}. Requires room level ${stage.level}. Adds 12% to room base earnings.`,workshopPreview(car,stage,i),`<button data-action="workshop" data-id="${car.id}" ${available?'':'disabled'}>${paid?'INSTALLED':i!==rank?'PREVIOUS COMMISSION REQUIRED':gate.ok?'COMMISSION · '+formatCoins(workshopCost(car))+' COINS':safe(gate.reason)}</button>`,`WORKSHOP ${i+1} / 4`,paid?'workshop-owned':available?'':'locked')}).join('')}}
 if(shopPage==='engineering')body=[['station','Faster Service','Reduce station arrival time by 9 seconds each level.',state.stationBoost,4],['comfort','Velvet & Brass','Raise every carriage’s income 6% per level.',state.comfort,5]].map(([id,title,desc,level,max])=>shopCard(title,`${desc} · Level ${level}/${max}`,path(id==='station'?'car-engine.png':'car-sleeper.png'),`<button data-action="train-upgrade" data-type="${id}" ${level>=max||state.coins<trainUpgradeCost(state,id)?'disabled':''}>${level>=max?'FULLY UPGRADED':'UPGRADE · '+formatCoins(trainUpgradeCost(state,id))+' COINS'}</button>`,'RAILWAY ENGINEERING')).join('');
 if(shopPage==='stampworks')body=STAMP_PROJECTS.map(p=>shopCard(p.name,p.desc,path(p.id==='postcards'?'car-observatory.png':p.id==='concierge'?'car-sleeper.png':'car-cafe.png'),`<button data-action="stamp-project" data-type="${p.id}" ${state.stampProjects.includes(p.id)||state.stamps<p.cost?'disabled':''}>${state.stampProjects.includes(p.id)?'COMPLETED':'REDEEM · '+p.cost+' STAMPS'}</button>`,'THE POSTCARD OFFICE')).join('');
 if(shopPage==='decoration')body=DECOR.map(d=>shopCard(d.name,d.desc,path(d.id==='flowers'?'car-garden.png':d.id==='lanterns'?'car-cafe.png':'car-arcade.png'),`<button data-action="decor" data-type="${d.id}" ${state.decor.includes(d.id)||state.coins<d.cost?'disabled':''}>${state.decor.includes(d.id)?'INSTALLED':'DECORATE · '+formatCoins(d.cost)+' COINS'}</button>`,'A LITTLE EXTRA MAGIC')).join('');
 if(shopPage==='heritage')body='<div class="route-note">Optional late-game projects preserve your railway. They are permanent commemorative achievements, not required progression.</div>'+HERITAGE_PROJECTS.map(p=>shopCard(p.name,`${p.stops.toLocaleString()} lifetime arrivals · ${formatCoins(p.coins)} coins · ${p.stamps} stamps`,path('car-library.svg'),`<button data-action="heritage" data-type="${p.id}" ${heritageGate(state,p.id)?'':'disabled'}>${state.heritageProjects.includes(p.id)?'COMMEMORATED':'FUND PROJECT'}</button>`,'LONG-TERM LEGACY')).join('');
 if(shopPage==='paint')body=ENGINES.map(e=>shopCard(e.name,e.era+' · '+(state.ownedEngines.includes(e.id)?'Owned':`Unlock after ${e.stops} lifetime stops · ${formatCoins(e.coins)} coins · ${e.stamps} stamps`),path(e.asset),`<button data-action="engine" data-type="${e.id}" ${state.engine===e.id||!engineGate(state,e.id)?'disabled':''}>${state.engine===e.id?'IN SERVICE':state.ownedEngines.includes(e.id)?'PUT INTO SERVICE':'UNLOCK ENGINE'}</button>`,'ENGINE CLASS')).join('')+PAINTS.map(p=>shopCard(p.name,`Change the engine finish. ${p.stampCost?p.stampCost+' stamps required.':'Classic railway colors.'}`,path(ENGINES.find(e=>e.id===state.engine)?.asset||'car-engine.png'),`<button data-action="paint" data-type="${p.id}" ${state.trainPaint===p.id||(!state.ownedPaints.includes(p.id)&&(state.coins<p.cost||state.stamps<p.stampCost))?'disabled':''}>${state.trainPaint===p.id?'CURRENT FINISH':state.ownedPaints.includes(p.id)?'APPLY':'UNLOCK · '+(p.cost?formatCoins(p.cost)+' COINS':'')+(p.cost&&p.stampCost?' + ':'')+(p.stampCost?p.stampCost+' STAMPS':'')}</button>`,'ENGINE LIVERY','',LIVERY_FILTERS[p.id])).join('');
 el('drawer-body').innerHTML=tabs+`<div class="cards">${body}</div>`;}
function renderJournal(){journalPage=['postcards','achievements','log','route','ledger','stories','manifest','ranks','blueprints'].includes(journalPage)?journalPage:'postcards';el('drawer-kicker').textContent='MEMORIES OF THE OPEN RAIL';el('drawer-title').textContent='The Travel Journal';const tabs=tabbar([['postcards','POSTCARDS'],['blueprints','BLUEPRINTS'],['achievements','ACHIEVEMENTS'],['route','ROUTE'],['ledger','SERVICE LEDGER'],['ranks','RAILWAY RANK'],['stories','STORIES'],['manifest','PASSENGERS'],['log','GUESTBOOK']],journalPage,'journal-page');let body='';
 if(journalPage==='postcards')body=`<div class="journal-grid">${DESTINATIONS.map((d,i)=>`<div class="postcard ${state.postcards.includes(d.id)?'':'unknown'}"><div class="art">${state.postcards.includes(d.id)?`<img src="${regionPicture(d.region)}" alt="Illustrated view of ${safe(d.name)}" loading="lazy"><img class="postcard-station" src="${path('station-'+d.id+'.svg')}" alt="${safe(d.name)} station" loading="lazy">`:''}</div><h3>${state.postcards.includes(d.id)?safe(d.name):'???'}</h3><p>${state.postcards.includes(d.id)?safe(d.postcard):'Explore the route to discover this view.'}</p></div>`).join('')}</div>`;
 if(journalPage==='achievements')body=`<div class="sticker-list">${ACHIEVEMENTS.map(a=>`<div class="sticker ${state.achievements.includes(a.id)?'':'missing'}"><strong>${state.achievements.includes(a.id)?'✦ ': '◇ '}${safe(a.title)}</strong><small>${safe(a.detail)} · +${a.reward} stamp${a.reward>1?'s':''}</small></div>`).join('')}</div>`;
 if(journalPage==='ledger')body=`<div class="service-intro"><div class="superline">THE LONG DISTANCE LEDGER</div><h3>${Math.floor(state.serviceSeconds/3600).toLocaleString('en-US')} hours in service</h3><p>No streaks and no mandatory visits. The Everline records actual active service and up to eight hours of time away. Masterwork rooms and these optional medals are designed as month-to-year ambitions.</p></div><div class="ledger-grid">${SERVICE_MILESTONES.map(m=>{const earned=state.serviceClaims.includes(m.id),h=state.serviceSeconds/3600,pct=Math.min(100,h/m.hours*100);return `<article class="ledger-medal ${earned?'complete':''}"><div class="medal-symbol">${earned?'✦':'✧'}</div><div><div class="small-kicker">${m.hours.toLocaleString('en-US')} SERVICE HOURS · +${m.stamps} STAMPS</div><h3>${safe(m.name)}</h3><div class="ledger-track"><i style="width:${pct}%"></i></div><small>${earned?'COMPLETED':Math.floor(h).toLocaleString('en-US')+' / '+m.hours.toLocaleString('en-US')+' HOURS'}</small></div></article>`}).join('')}</div>`;
 if(journalPage==='manifest')body='<div class="route-note">Passenger names and travel purposes are recorded here. Boarding and alighting take place only at a station.</div>'+state.cars.map((c,i)=>`<article class="story-card"><div class="superline">CARRIAGE ${i+1} · ${c.riders} ABOARD</div><h3>${safe(CARRIAGES[c.type].name)}</h3>${passengerManifest(c).map(p=>`<p><b>${safe(p.name)}</b> · ${safe(p.purpose)}</p>`).join('')||'<p>Awaiting the next station.</p>'}</article>`).join('');
 if(journalPage==='stories')body='<div class="route-note">Follow the travelers across the line. Chapters are revealed at station arrivals; finished stories earn a Stamp.</div>'+TALES.map(t=>`<article class="story-card"><div class="superline">TRAVELER'S TALE · ${t.lines.filter((_,i)=>state.tales.includes(t.id+':'+i)).length}/3</div><h3>${safe(t.name)}</h3>${t.lines.map((line,i)=>`<p>${state.tales.includes(t.id+':'+i)?safe(line):'Undiscovered chapter'}</p>`).join('')}</article>`).join('');
 if(journalPage==='log')body=`<div class="sticker-list">${state.log.length?state.log.map(x=>`<div class="sticker"><strong>Stop ${x.stop}</strong><small>${safe(x.text)}</small></div>`).join(''):'<p>No stories just yet. Let the journey begin.</p>'}</div>`;
 if(journalPage==='ranks'){const rank=serviceRank(state),next=SERVICE_RANKS[rank],prev=rank?SERVICE_RANKS[rank-1].stops:0;const percent=next?Math.max(0,Math.min(100,(state.totalStops-prev)/(next.stops-prev)*100)):100;body=`<div class="route-note rank-hero"><div class="small-kicker">LIFETIME SERVICE · ${rank}/10</div><h3>${rank?safe(SERVICE_RANKS[rank-1].name):'New railway'}</h3><p>${state.totalStops.toLocaleString()} completed stops ${next?' / '+next.stops.toLocaleString()+' for '+safe(next.name):' · All service ranks achieved'}</p><progress max="100" value="${percent}" aria-label="Progress to next service rank"></progress></div><div class="rank-grid">`+SERVICE_RANKS.map((r,i)=>`<article class="story-card rank-card"><div class="small-kicker">RANK ${String(i+1).padStart(2,'0')}</div><h3>${safe(r.name)}</h3><p>${r.stops.toLocaleString()} lifetime stops · ${r.stamps} stamps</p><button class="rank-claim" data-action="claim-rank" data-type="${r.id}" ${state.totalStops>=r.stops&&!state.rankClaims.includes(r.id)?'':'disabled'}>${state.rankClaims.includes(r.id)?'CLAIMED':state.totalStops>=r.stops?'CLAIM REWARD':'IN PROGRESS'}</button></article>`).join('')+'</div>';}
 if(journalPage==='blueprints'){const known=new Set(state.knownBlueprints||[]),aboard=new Set(state.cars.map(c=>c.type));body=`<div class="route-note catalog-header"><b>Blueprint collection · ${known.size}/${TYPE_ORDER.length}</b><p>Discover every unique room across your timetables. Your permanent collection survives a new season. At most 25 rooms travel together; refit an existing carriage to explore the rest.</p></div>`+TYPE_ORDER.map(t=>shopCard(CARRIAGES[t].name,`${SERVICE_CATALOG[t].category} · ${known.has(t)?'Discovered':`Requires ${CARRIAGES[t].unlock} current stops and ${CARRIAGES[t].minCars} carriages`}`,roomPicture(t),'',aboard.has(t)?'ABOARD':known.has(t)?'COLLECTED':'UNDISCOVERED',known.has(t)?'':'locked')).join('');body=`<div class="cards">${body}</div>`;}
 if(journalPage==='route')body=`<div class="stats-line">YOUR TRAIN: ${state.cars.length} CARRIAGES · ${capacity(state)} PASSENGERS · ${satisfaction(state)}% HAPPINESS · ${formatCoins(incomeRate(state)*3600)} COINS / HR<br>PLACES VISITED: ${state.seen.length}/${DESTINATIONS.length} · LIFETIME ARRIVALS: ${state.totalStops} · SEASON ${state.legacyCount+1}</div><div class="route-map" aria-label="Railway route map">${REGIONS.map((r,i)=>`<button class="route-stop ${r.id===state.activeRegion?'here':''}" data-action="${state.regionsUnlocked.includes(r.id)?'travel-region':'unlock-region'}" data-type="${r.id}" ${r.id===state.activeRegion||!regionGate(state,r.id).ok?'disabled':''} aria-label="${safe(r.name)} · ${state.regionsUnlocked.includes(r.id)?'unlocked':'locked'}"><span>${String(i+1).padStart(2,'0')}</span>${safe(r.name)}</button>`).join('')}</div><div class="route-note">Each chapter introduces an illustrated landscape and two stations. Scenic roaming spends six stops in each unlocked region before traveling onward; you can choose a route and stay there instead.</div><div class="route-policy"><span>SCENIC AUTOPILOT: ${state.autoTour?'ROAMING EVERY 6 STOPS':'STAYING ON SELECTED ROUTE'}</span><button data-action="tour-mode" aria-label="Toggle automatic travel between unlocked regions">${state.autoTour?'STAY IN THIS REGION':'ENABLE SCENIC ROAMING'}</button></div><div class="region-grid">${REGIONS.map(r=>{const owned=state.regionsUnlocked.includes(r.id),gate=regionGate(state,r.id),active=state.activeRegion===r.id;return `<article class="region-ticket ${active?'current-region':''}" style="--region-accent:${r.accent}"><div class="region-preview"><img src="${regionPicture(r.id)}" alt="Illustrated ${safe(r.name)} route scenery" loading="lazy"/></div><div class="region-mini">${safe(r.subtitle)}</div><h3>${safe(r.name)}</h3><p>${safe(DESTINATIONS.filter(d=>d.region===r.id).map(d=>d.name).join(' · '))}</p><button data-action="${owned?'travel-region':'unlock-region'}" data-type="${r.id}" ${active||(!owned&&!gate.ok)?'disabled':''}>${active?'CURRENT ROUTE':owned?'TRAVEL HERE':gate.ok?'UNLOCK · '+r.stamps+' STAMPS':safe(gate.reason)}</button></article>`}).join('')}</div><div class="sticker-list"><div class="sticker"><strong>OPTIONAL · NEW TIMETABLE</strong><small>After 20 carriages and three railway regions, begin a fresh season with +16% permanent earnings. Keep all Stamps, discoveries, cosmetics, and regional licences; carriages restart. Never required.</small><button data-action="new-season" ${canStartSeason(state)?'':'disabled'}>${canStartSeason(state)?'BEGIN A NEW SEASON':'REQUIRES 20 CARRIAGES + 3 REGIONS'}</button></div></div>`;
 el('drawer-body').innerHTML=tabs+body;}
function openDrawer(page){if(scenic)setScenic(false);mode=page;el('drawer').showModal();el('drawer').scrollTop=0;for(const btn of /** @type {NodeListOf<HTMLButtonElement>} */(document.querySelectorAll('[data-page]'))){const selected=btn.dataset.page===page;btn.classList.toggle('selected',selected);selected?btn.setAttribute('aria-current','page'):btn.removeAttribute('aria-current')};if(page==='shop')renderShop();else renderJournal();el('drawer-body').scrollTop=0;}
function closeDrawer(){if(el('drawer').open)el('drawer').close();mode='train';for(const btn of /** @type {NodeListOf<HTMLButtonElement>} */(document.querySelectorAll('[data-page]'))){const selected=btn.dataset.page==='train';btn.classList.toggle('selected',selected);selected?btn.setAttribute('aria-current','page'):btn.removeAttribute('aria-current')};}
function takeSighting(){if(!active)return;const d=active;active=null;if(claimSighting(state,d.id))progress('A rare '+d.name+'! +1 postcard stamp and 35 coins.');else progress('The '+d.name+' is safely recorded in your journal.');}
function act(button){const action=button.dataset.action,id=Number(button.dataset.id),type=button.dataset.type;
 if(action==='upgrade'){const res=upgradeCar(state,id);if(res.ok){scene.pop(scene.width/2,scene.height*.46);maybeTutorial(1);progress('Restoration booked · finishes after its service timer.')}else toast(res.reason)}
 if(action==='next-grade'){const quote=gradeUpgradeQuote(state,id);if(quote.ok&&confirm('Restore this room to level '+quote.target+' for '+formatCoins(quote.cost)+' coins?')){const result=buyNextGrade(state,id);if(result.ok){scene.pop(scene.width/2,scene.height*.46);progress('Grade restoration booked · all work takes time.')}else toast(result.reason)}else if(!quote.ok)toast(quote.reason);}
 if(action==='workshop'){const result=buyWorkshop(state,id);if(result.ok){scene.pop(scene.width/2,scene.height*.5);progress('Workshop commission installed · new artwork and earnings bonus.')}else toast(result.reason)}
 if(action==='claim-rank')progress(claimServiceRank(state,type)?'Service rank reward claimed.':'Rank not yet available or already claimed.');
 if(action==='hire'){if(hireResident(state,id))progress('Crew booked · they board at the next station, when their bonuses begin.');else toast('That resident cannot be hired yet.')}
 if(action==='move'){if(moveCar(state,id,Number(button.dataset.direction))){scene.focus(state.selected);progress('The carriages were rearranged.')}}
 if(action==='build'){const result=buildCar(state,type);if(result.ok){scene.focus(state.selected);scene.pop(scene.width/2,scene.height*.52);progress(CARRIAGES[type].name+' construction started.')}else toast(result.reason)}
 if(action==='refit'){const gate=refitGate(state,id,type);if(gate.ok&&confirm('Refit as '+CARRIAGES[type].name+' for '+formatCoins(gate.cost)+' coins at the next stop? The room level and crew stay.')){const result=queueRefit(state,id,type);progress(result.ok?'Refit booked · completes at the next station.':result.reason);}else if(!gate.ok)toast(gate.reason);}
 if(action==='train-upgrade'){progress(buyTrainUpgrade(state,type)?'Your locomotive has been improved; travel time is shorter.':'Not affordable or already complete.')}
 if(action==='decor'){progress(buyDecor(state,type)?'A charming new decoration appears on your train.':'Not affordable or already installed.')}
 if(action==='engine')progress(selectEngine(state,type)?'Locomotive changed.':'Engine not yet available.');
 if(action==='heritage')progress(buyHeritage(state,type)?'Heritage project commemorated.':'Project requirements not met.');
 if(action==='paint'){progress(buyPaint(state,type)?'Engine livery changed.':'Cannot unlock this livery yet.')}
 if(action==='stamp-project')progress(buyStampProject(state,type)?'Postcard Office project complete.':'Requires more Stamps or already owned.');
 if(action==='unlock-region'){if(unlockRegion(state,type)){progress('New chapter unlocked! Welcome to '+REGIONS.find(r=>r.id===type).name+'.')}else toast(regionGate(state,type).reason)}
 if(action==='travel-region'){if(travelRegion(state,type))progress('Now traveling the '+REGIONS.find(r=>r.id===type).name+'.');else toast('Unlock the region first.')}
 if(action==='tour-mode')progress(setAutoTour(state,!state.autoTour)?(state.autoTour?'Auto-tour enabled: new scenery after six stops.':'Staying on this route.'):'Could not change touring mode.');
 if(action==='new-season'){if(canStartSeason(state)&&confirm('Begin a new timetable? This resets carriages, rooms, coins, and current stops. Stamps, routes, postcards, and cosmetics remain.')){startSeason(state);scene.state=state;scene.focus(0);progress('A fresh season begins · permanent income bonus!')}else if(!canStartSeason(state))toast('Unlock three regions and build twenty carriages first.')}
 if(action==='open-shop'){shopPage='cars';openDrawer('shop');}
 if(action==='open-supplies'){shopPage='supplies';openDrawer('shop');}
 if(action==='restock'){const q=orderSupply(state,id,Number(type));if(q.ok)progress('Supplies ordered · delivery in '+timeText(q.seconds));else toast(q.reason);}
 if(action==='restock-train'){const n=orderTrainSupplies(state);if(n)progress(n+' train supply orders booked.');else toast('No affordable orders right now.');}
 if(action==='restock-all'){const n=orderAllSupplies(state,id);if(n)progress(n+' supply orders booked.');else toast('No supplies can be ordered right now.');}
 if(action==='skip-tutorial'||action==='finish-tutorial'){state.tutorial=3;persist(true);renderTour();}
}
// Sound is opt-in and synthesized locally. No network, autoplay, or copyrighted music.
let audioContext=null,railGain=null,railSource=null,audioVolume=.7;try{const v=localStorage.getItem('everline-volume');if(v!==null&&Number.isFinite(Number(v)))audioVolume=Math.max(0,Math.min(1,Number(v)))}catch{}
async function toggleAudio(enabled){audioEnabled=enabled;if(!enabled){if(audioContext)await audioContext.suspend();return;}try{if(!audioContext){audioContext=new AudioContext();const rate=audioContext.sampleRate,buffer=audioContext.createBuffer(1,rate*2,rate),a=buffer.getChannelData(0);let noise=0;for(let i=0;i<a.length;i++){noise=.94*noise+.06*(Math.random()*2-1);a[i]=noise;}railSource=audioContext.createBufferSource();railSource.buffer=buffer;railSource.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=340;railGain=audioContext.createGain();railGain.gain.value=.018*audioVolume;railSource.connect(filter).connect(railGain).connect(audioContext.destination);railSource.start();}await audioContext.resume();}catch{audioEnabled=false;toast('Audio is unavailable in this browser.');}}
function stationChime(){if(!audioEnabled||!audioContext||audioContext.state!=='running')return;for(const [i,hz] of [440,554,659].entries()){const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.13;o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.038*audioVolume+.0001,t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+.4);o.connect(g).connect(audioContext.destination);o.start(t);o.stop(t+.42);}}
function setScenic(on){scenic=on;scene.scenic=on;el('game').classList.toggle('scenic-mode',on);el('scenic').setAttribute('aria-pressed',String(on));el('scenic').querySelector('span').textContent=on?'Exit scenic view':'Scenic view';el('photo').hidden=!on;el('zoom-in').hidden=!on;el('zoom-out').hidden=!on;if(!on)scene.setZoom(1);for(const selector of ['.hud','.nav','#inspector','#tour','#sighting']){const item=document.querySelector(selector);if(item instanceof HTMLElement)item.inert=on;}if(on)el('scenic').focus();}
el('scenic').addEventListener('click',()=>setScenic(!scenic));el('zoom-in').addEventListener('click',()=>scene.setZoom(scene.zoom+.15));el('zoom-out').addEventListener('click',()=>scene.setZoom(scene.zoom-.15));
el('photo').addEventListener('click',()=>{try{scene.canvas.toBlob(blob=>{if(!blob){toast('Postcard capture unavailable.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='everline-postcard.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);},'image/png');}catch{toast('Postcard capture unavailable in this browser.');}});
document.addEventListener('visibilitychange',()=>{if(audioContext){if(document.hidden)audioContext.suspend();else if(audioEnabled)audioContext.resume().catch(()=>{});}});
function fleetHTML(){return `<section class="fleet-panel"><h3>Railway fleet</h3><p>${fleetUnlocked?'Three independent local trains. Switching saves the current journey. Each train has its own coins, stamps and progress.':'Unlock additional train slots after building 20 carriages and visiting three regions.'}</p>${[0,1,2].map(i=>`<button data-settings-action="fleet" data-slot="${i}" ${i===activeSlot||(!fleetUnlocked&&i!==0)?'disabled':''}>${i===activeSlot?'CURRENT TRAIN':`OPEN TRAIN ${i+1}`}</button>`).join('')}</section>`;}
/** @type {any} */
let installPrompt=null;let installCompleted=false;
function installedApp(){return installCompleted||window.matchMedia('(display-mode: standalone)').matches||Boolean(/** @type {any} */(navigator).standalone);}
function installPanelHTML(){const native=Boolean(/** @type {any} */(window).__TAURI_INTERNALS__);const hosted=!native&&['https:','http:'].includes(location.protocol);const installed=installedApp()||native;return `<section class="fleet-panel install-panel" aria-labelledby="install-title"><div class="install-heading"><img src="${path('icon-192.png')}" alt="" width="56" height="56"/><div><h3 id="install-title">The Everline app</h3><p>${installed?'Application window':hosted?'Add this railway to your desktop or home screen.':'Standalone edition · play without installation'}</p></div></div>${!installed&&hosted?(installPrompt?'<button data-settings-action="install">INSTALL THE EVERLINE</button>':'<p>Chrome or Edge: use the browser’s Install app menu. On iPhone/iPad, use Safari’s Share → Add to Home Screen. On supported Mac Safari versions, use File → Add to Dock.</p>'):installed?'<p>Your save stays local to this application profile. Export it to move your railway to another device.</p>':'<p>Open the hosted Everline website for browser installation. Your save is local to its browser profile and origin.</p>'}<p class="install-note">Back up your train before clearing browser data or uninstalling.</p></section>`;}
function refreshInstallPanel(){const panel=el('install-panel-slot');if(panel)panel.innerHTML=installPanelHTML();}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;refreshInstallPanel();});
window.addEventListener('appinstalled',()=>{installCompleted=true;installPrompt=null;refreshInstallPanel();});
async function requestInstall(){if(!installPrompt||installedApp())return;const prompt=installPrompt;installPrompt=null;refreshInstallPanel();try{await prompt.prompt();const result=await prompt.userChoice;if(result?.outcome==='accepted'){installCompleted=true;toast('Everline added to your applications.');}else toast('Installation dismissed.');}catch{toast('Use your browser menu to install Everline.');}refreshInstallPanel();}
function settingsHTML(){return `<div class="setting-line"><label for="train-name">Train name</label><input id="train-name" maxlength="64" value="${safe(state.trainName)}" autocomplete="off"/><button data-settings-action="rename">SAVE NAME</button></div><div class="setting-line"><label for="audio-setting">Railway ambience & station chime</label><input id="audio-setting" type="checkbox" ${audioEnabled?'checked':''}/></div><div class="setting-line"><label for="volume-setting">Ambience volume</label><input id="volume-setting" type="range" min="0" max="100" step="5" value="${Math.round(audioVolume*100)}"/></div><div class="setting-line"><label for="power-setting">Low-power rendering (30 FPS cap)</label><input id="power-setting" type="checkbox" ${lowPower?'checked':''}/></div><div class="setting-line"><span>Animate scenery and residents</span><input id="motion-setting" type="checkbox" ${motion?'checked':''} aria-label="Toggle game animation"/></div><div class="setting-line"><label for="season-setting">Scenery season</label><select id="season-setting">${['auto',...SEASONS].map(season=>`<option value="${season}" ${state.seasonChoice===season?'selected':''}>${season==='auto'?'Automatic':season}</option>`).join('')}</select></div>${fleetHTML()}<div id="install-panel-slot">${installPanelHTML()}</div><div class="stats-line">You have visited <b>${state.seen.length}</b> destinations. While away, the train earns up to eight hours of coins. Your train saves in this browser only, including three local recovery snapshots. Another open tab will pause its saving if this train changes elsewhere. Back up with Export Save before clearing browser data or changing devices. No accounts or in-game purchases.</div><div class="settings-actions"><button data-settings-action="export">EXPORT SAVE</button><button data-settings-action="import">IMPORT SAVE ↓</button><button data-settings-action="reset">RESET JOURNEY</button><button data-settings-action="recover">RESTORE LOCAL BACKUP</button><button data-settings-action="reload">RELOAD SAVED TRAIN</button></div><label for="save-json" class="superline">IMPORT A SAVE (JSON)</label><textarea id="save-json" spellcheck="false" placeholder="Paste a saved Everline JSON here to restore progress (max 200 KB)"></textarea><button class="gold-btn" data-settings-action="apply">VALIDATE & RESTORE</button>`}
function exportSave(){persist(true);const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='everline-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function settingsAction(btn){const what=btn.dataset.settingsAction;if(what==='install'){void requestInstall();return;}if(what==='fleet'){const target=Number(btn.dataset.slot);if(!fleetUnlocked||!Number.isInteger(target)||target<0||target>=3||target===activeSlot||saveConflict)return;try{state.lastTime=Date.now();saveGame(gameStorage,state);localStorage.setItem('everline-active-slot',String(target));location.reload();}catch{toast('Unable to switch safely. Export this train first.');}return;}if(what==='rename'){renameTrain(state,el('train-name').value);el('train-name').value=state.trainName;progress('Train name saved.');return;}if(what==='reload'){location.reload();return}if(what==='export')exportSave();if(what==='import')el('save-json').focus();if(what==='apply'){try{const t=el('save-json').value;if(t.length>200000)throw Error('Save is too large');const parsed=validateState(JSON.parse(t));state=parsed;scene.state=state;active=null;persist(true);refresh();el('settings-dialog').close();toast('Your saved journey has been restored.')}catch(err){toast('Cannot import: '+(err?.message||'invalid save'))}}
 if(what==='recover'){try{const found=loadBackup(gameStorage);if(!found.state)throw Error('No available backup');state=found.state;scene.state=state;scene.focus(state.selected);persist(true);refresh();el('settings-dialog').close();toast('Restored '+(found.recovered?'from a recovery save.':'current save.') )}catch{toast('No valid local backups were found.')}}
 if(what==='reset'){if(confirm('Begin a fresh journey? All local progress will be replaced. Export your save first if you want a backup.')){try{clearGame(gameStorage)}catch{}state=initialState();scene.state=state;scene.focus(0);active=null;persist(true);refresh();el('settings-dialog').close();toast('A new Everline journey begins.')}}}
document.body.addEventListener('click',e=>{const btn=/** @type {any} */(e.target).closest('button');if(!btn)return;if(btn.dataset.action)act(btn);
 if(btn.dataset.page){if(btn.dataset.page==='train')closeDrawer();else if(mode!==btn.dataset.page)openDrawer(btn.dataset.page)}
 if(btn.dataset.catalogFilter){catalogFilter=btn.dataset.catalogFilter;renderShop();}
 if(btn.dataset.shopPage){shopPage=btn.dataset.shopPage;renderShop();el('drawer-body').scrollTop=0}
 if(btn.dataset.journalPage){journalPage=btn.dataset.journalPage;renderJournal()}
 if(btn.dataset.settingsAction)settingsAction(btn);
});
el('collect').addEventListener('click',()=>{const got=collect(state);if(got>0){scene.pop(scene.width*.54,60);maybeTutorial(0);progress('Collected '+formatCoins(got)+' coins!')}else toast('Your rooms will earn more coins shortly.')});
el('settings').addEventListener('click',()=>{el('settings-body').innerHTML=settingsHTML();el('settings-dialog').showModal();el('audio-setting').addEventListener('change',e=>toggleAudio(/** @type {HTMLInputElement} */(e.target).checked));el('volume-setting').addEventListener('input',()=>{audioVolume=Number(el('volume-setting').value)/100;try{localStorage.setItem('everline-volume',String(audioVolume))}catch{}});el('power-setting').addEventListener('change',e=>{lowPower=/** @type {HTMLInputElement} */(e.target).checked;scene.lowPower=lowPower;scene.resize();try{localStorage.setItem('everline-low-power',String(lowPower))}catch{};});el('season-setting').addEventListener('change',e=>{setVisualSeason(state,el('season-setting').value);persist(true);refresh();});el('motion-setting').addEventListener('change',e=>{motion=/** @type {any} */(e.target).checked;scene.motion=motion;try{localStorage.setItem('everline-motion',String(motion))}catch{};toast(motion?'Animation enabled.':'Reduced animation enabled.')});});
el('close-drawer').addEventListener('click',closeDrawer);el('close-settings').addEventListener('click',()=>el('settings-dialog').close());el('drawer').addEventListener('close',()=>{mode='train';for(const btn of /** @type {NodeListOf<HTMLButtonElement>} */(document.querySelectorAll('[data-page]'))){const selected=btn.dataset.page==='train';btn.classList.toggle('selected',selected);selected?btn.setAttribute('aria-current','page'):btn.removeAttribute('aria-current')}});el('sighting').addEventListener('click',takeSighting);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&scenic){setScenic(false);return;}if(e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement||e.target instanceof HTMLSelectElement||e.target instanceof HTMLButtonElement||el('settings-dialog').open||scenic)return;if((e.key==='s'||e.key==='S')&&!el('drawer').open){openDrawer('shop')}if((e.key==='j'||e.key==='J')&&!el('drawer').open){openDrawer('journal')}if(e.key==='Escape'&&el('drawer').open)closeDrawer()});
function operationSignature(){return state.cars.map(c=>[c.type,Boolean(c.buildRemaining),Boolean(c.upgradeRemaining),c.level,c.staff,...[0,1,2].map(i=>stockRemaining(c,i)>0?'stock':deliveryRemaining(c,i)>0?'order':'empty')].join(':')).join('|');}
function update(){if(document.hidden)return;const beforeOperations=operationSignature();const now=Date.now(),seconds=Math.max(0,Math.min(28800,(now-lastTick)/1000));lastTick=now;const result=tick(state,seconds,{offline:document.hidden});
  if(audioEnabled&&railGain&&audioContext)railGain.gain.setTargetAtTime(audioVolume*(.008+.025*journeyMotion(state).speed),audioContext.currentTime,.2);
  if(result.arrivals.length){if(mode==='journal'&&['manifest','stories','log','postcards','ranks'].includes(journalPage)){const focused=document.activeElement;const tab=focused instanceof HTMLElement?focused.dataset.journalPage:null;renderJournal();if(tab)document.querySelector(`[data-journal-page="${tab}"]`)?.['focus']?.();}stationChime();const a=result.arrivals.at(-1);toast((window.innerWidth<650?'ARRIVED · '+a.destination.name+' · +'+formatCoins(a.fare)+' fares': 'NOW ARRIVING · '+a.destination.name+' · '+a.boarding+' boarding, '+a.alighting+' leaving · +'+formatCoins(a.fare)+' fares')+(a.isNew?' · New postcard!':''));scene.pop(scene.width*.68,scene.height*.4)}
  if(result.sighting){const [seed,val]=[state.seed,((state.seed>>>2)%997)/997];active={...result.sighting,x:Math.max(120,Math.min(1400,450+val*700)),y:300};}
  if(active&&Date.now()-active.created>170000)active=null;
  if(beforeOperations!==operationSignature()){if(mode==='shop'&&['cars','supplies','workshop','refit'].includes(shopPage))renderShop();else if(mode==='journal'&&journalPage==='blueprints')renderJournal();}
  if(now-lastUi>500){lastUi=now;refresh();const building=state.cars.find(underConstruction),buildClock=document.querySelector('[data-build-clock]');if(buildClock&&building)buildClock.textContent=timeText(building.buildRemaining);const current=state.cars[state.selected];if(current)for(const node of document.querySelectorAll('[data-supply-clock]')){const i=Number(node.getAttribute('data-supply-clock'));node.textContent=timeText(deliveryRemaining(current,i)||stockRemaining(current,i));}if(current)for(const meter of document.querySelectorAll('[data-supply-meter]')){const i=Number(meter.getAttribute('data-supply-meter'));const percent=Math.min(100,100*stockRemaining(current,i)/stockCapacity(current,i));meter.setAttribute('aria-valuenow',String(Math.floor(percent)));const fill=meter.querySelector('span');if(fill)fill.style.width=percent+'%';}}persist();
}
setInterval(update,250);
refresh();if(recovered)setTimeout(()=>toast(['everline-save-v3','everline-save-v4','everline-save-v5'].includes(saveSource)?'Your earlier Everline save was migrated safely to v6.':'A local backup restored your train.'),600);else if(offline>1)setTimeout(()=>toast('Welcome back · +'+formatCoins(offline)+' coins earned while away.'),900);
